'use strict';
(function(root){const clone=v=>JSON.parse(JSON.stringify(v));class Practice{
constructor(hero=3,cell=3){this.you='practice';this.host=this.you;this.code='연습';this.room='practice';this.last=Date.now()/1000;this.state={status:'fight',t:0,revives:2,effects:[],boss:{hp:100000,maxHP:100000,sequence:-1,attackAt:3,resolveAt:3,exposedUntil:0,pattern:'crack',lane:400},players:[]};for(let i=0;i<4;i++){let h=i?i===1?10:i===2?8:1:hero,c=i?i===1?5:3:cell;this.state.players.push({id:i?'npc'+i:this.you,name:i?['','치유 연습 동료','궁수 연습 동료','전사 연습 동료'][i]:'나의 연습 캐릭터',hero:h,cell:c,job:RPG_DATA.characters[h].classes[c].name,level:60,role:i===1?'heal':i===2?'ranged':'guard',skills:RPG_DATA.skills.filter(s=>s.heroId===h&&s.cell===c).map(s=>s.name),hp:2500,maxHP:2500,attack:160,x:250+i*100,y:340,tx:250+i*100,ty:340,damage:0,defense:0,allyDefense:0,healing:0,allyHealing:0,rescues:0,mechanics:0,shield:0,guardUntil:0,prison:0,prisonUntil:0,attackAt:0,manualAt:-99,abilities:[],powerUntil:0,powerBonus:0,lastAttack:-99,lastCast:-99,cooldowns:[0,0,0,0]});const p=this.state.players.at(-1),profile=RPG_RAID_COMBAT.profile(p);p.role=profile.role;p.kit=profile.kit;p.attack*=profile.attackMultiplier;}}
hurt(p,n){if(root.RPG_SUPPORT_RAID){root.RPG_SUPPORT_RAID.hurt(this.state,p,n);return;}const s=this.state,owner=s.players.find(q=>q.id===(p.guardUntil>s.t?p.guardOwner:p.id)),reduced=n*Math.max(p.guardUntil>s.t?.4:0,p.spinGuardUntil>s.t?.3:0);if(owner){owner.defense+=reduced;if(owner!==p)owner.allyDefense+=reduced;}const absorb=Math.min(p.shield,n-reduced),sh=s.players.find(q=>q.id===p.shieldOwner);if(sh){sh.defense+=absorb;if(sh!==p)sh.allyDefense+=absorb;}p.shield-=absorb;p.hp=Math.max(0,p.hp-n+reduced+absorb);}
advance(dt){const s=this.state;if(s.status!=='fight')return;s.t+=dt;RPG_RAID_COMBAT.tick(s);const t=s.t,b=s.boss;s.effects=s.effects.filter(e=>t-e.at<2);for(const [i,p]of s.players.entries()){if(p.hp<=0)continue;if(p.prison>0){if(t>p.prisonUntil){p.prison=0;this.hurt(p,800);}continue;}if(i&&t-p.manualAt>3){const goal=RPG_RAID_NAVIGATION.destination(s,p);p.tx=goal.x;p.ty=goal.y;if(b.pattern==='crack'&&b.resolveAt>t&&Math.abs(p.x-b.lane)<90)p.tx=b.lane<400?600:200;}let dx=p.tx-p.x,dy=p.ty-p.y,len=Math.hypot(dx,dy),d=Math.min(len,105*dt*(1+(root.RPG_SUPPORT_RAID?.value(s,p,'speed')||0)));if(len){p.x+=dx/len*d;p.y+=dy/len*d;}if(t>=p.attackAt&&Math.hypot(p.x-400,p.y-190)<=(['heal','ranged'].includes(p.role)?280:110)){p.attackAt=t+1/(1+(root.RPG_SUPPORT_RAID?.value(s,p,'haste')||0));p.lastAttack=t;const prisoner=s.players.find(q=>q!==p&&q.prison>0);if(prisoner){prisoner.prison=Math.max(0,prisoner.prison-p.attack);if(!prisoner.prison)p.mechanics++;}else{let damage=Math.min(b.hp,p.attack*(1+(root.RPG_SUPPORT_RAID?.bonus(s,p)||0))*(1+(root.RPG_SUPPORT_RAID?.value(s,{roleUnit:b.roleUnit},'vulnerable')||0))*(b.exposedUntil>t?1.65:1));p.damage+=damage;b.hp-=damage;s.effects.push({kind:'hit',at:t,x:400,y:190,owner:p.id,value:Math.ceil(damage)});}}if(i)for(let slot=0;slot<4;slot++){const spec=p.kit[slot];if(spec.supportKit&&!root.RPG_SUPPORT_RAID.autoReady(s,p,slot))continue;if(p.cooldowns[slot]>t||spec.heal&&!s.players.some(q=>q.hp>0&&q.hp<q.maxHP*.82)||spec.buff&&p.powerUntil>t+1||['summon','dot'].includes(spec.effect)&&(p.abilities||[]).some(a=>a.slot===slot&&a.until>t+3)||!spec.supportKit&&slot===3&&b.exposedUntil<=t&&b.hp/b.maxHP>.3)continue;if(this.skill(p,slot))break;}}
let phase=Math.floor(t/12);if(phase>b.sequence){Object.assign(b,{sequence:phase,pattern:['crack','core','prison'][phase%3],resolveAt:t+3,lane:150+(phase*137+200)%500});if(b.pattern==='core')b.exposedUntil=t+7;}
if(b.resolveAt>0&&t>=b.resolveAt){if(b.pattern==='crack')s.players.filter(p=>Math.abs(p.x-b.lane)<85).forEach(p=>this.hurt(p,1000));if(b.pattern==='prison'){const p=s.players.find(p=>p.hp>0);if(p){p.prison=1200;p.prisonUntil=t+12;}}s.effects.push({kind:b.pattern,at:t,x:b.lane,y:250});b.resolveAt=0;}
if(t>=b.attackAt){b.attackAt=t+2;const p=s.players.filter(p=>p.hp>0).sort((a,b)=>Math.hypot(a.x-400,a.y-190)-Math.hypot(b.x-400,b.y-190))[0];if(p)this.hurt(p,300);}
if(b.hp<=0){s.status='clear';s.reason='폐광의 거신 토벌 · 연습';}else if(t>=300||s.players.every(p=>p.hp<=0)){s.status='failed';s.reason='연습 종료';}}
skill(p,slot){return RPG_RAID_COMBAT.cast(this.state,p,slot);}
async command(cmd,arg={}){this.advance(Math.min(1,Date.now()/1000-this.last));this.last=Date.now()/1000;const s=this.state,p=s.players[0];if(cmd==='move'){p.tx=Math.max(60,Math.min(740,arg.x));p.ty=Math.max(110,Math.min(480,arg.y));p.manualAt=s.t;}if(cmd==='skill')this.skill(p,arg.slot);if(cmd==='revive'&&p.hp<=0&&s.revives>0){p.hp=p.maxHP*.5;s.revives--;}if(cmd==='rescue'){const q=s.players[arg.target];if(q&&q.hp<=0&&Math.hypot(q.x-p.x,q.y-p.y)<80){if(p.rescueTarget!==arg.target){p.rescueTarget=arg.target;p.rescueSince=s.t;}if(s.t-p.rescueSince>=3){q.hp=q.maxHP*.3;p.rescues++;p.rescueTarget=-1;}}}return clone({room:this.room,code:this.code,host:this.host,you:this.you,state:s,wallet:0,daily:0,reward:0,practice:true});}}
root.RPG_RAID_PRACTICE=Practice;})(typeof window!=='undefined'?window:globalThis);
